const dataRaw=$('Attempts Range').first().json||{};
const countRaw=$('Count Range').first().json||{};
const rowsAll=Array.isArray(dataRaw.data)?dataRaw.data:null;
const countRows=Array.isArray(countRaw.data)?countRaw.data:null;
const expected=countRows?.[0]?.count?.id;
const meta=$('Validate Range').first().json;
if(!rowsAll || expected===undefined || expected===null){
  return [{json:{ok:false,error:'Directus non ha restituito una risposta valida. Nessun KPI viene calcolato.',error_code:'DB_RESPONSE_INVALID'}}];
}
const expectedN=Number(expected||0);
if(rowsAll.length!==expectedN){
  return [{json:{ok:false,error:`Dataset parziale: ricevute ${rowsAll.length} righe su ${expectedN}. Nessun KPI viene calcolato.`,error_code:'DATASET_TRUNCATED',rows_returned:rowsAll.length,rows_expected:expectedN}}];
}
const prodVal=v=>v===false||v===0||String(v).toLowerCase()==='false';
const testVal=v=>v===true||v===1||String(v).toLowerCase()==='true';
const rows=rowsAll.filter(a=>prodVal(a.test_mode));
const testCount=rowsAll.filter(a=>testVal(a.test_mode)).length;
const envUnknown=rowsAll.length-rows.length-testCount;
const div=(a,b)=>b?a/b:null;
const bump=(o,k)=>{const key=(k===null||k===undefined||String(k).trim()==='')?'missing':String(k);o[key]=(o[key]||0)+1};
const validRespondent=v=>['human','ivr','ai_voice','voicemail'].includes(String(v||'').toLowerCase());
const purposeAnalysisAvailable=v=>!['','unknown','unkown'].includes(String(v??'').trim().toLowerCase());
const purposeDetermined=v=>['commercial','support','private','reception'].includes(String(v||'').toLowerCase());
const serviceDetermined=v=>!['','unknown','unkown','none'].includes(String(v??'').trim().toLowerCase());
const purpose={},service_category={};let completed=0,spam=0,rOk=0,pAnalysis=0,pDetermined=0,sDetermined=0;const buckets={};
for(let dt=DateTime.fromISO(meta.from_local,{zone:'Europe/Rome'});dt<=DateTime.fromISO(meta.to_local,{zone:'Europe/Rome'});dt=dt.plus({days:1}))buckets[dt.toISODate()]={date:dt.toISODate(),calls_registered:0,completed:0,spam:0,respondent_ok:0};
for(const a of rows){
  const dt=DateTime.fromISO(a.start_time,{setZone:true});
  const local=dt.isValid?dt.setZone('Europe/Rome').toISODate():null;
  const b=local?buckets[local]:null;if(b)b.calls_registered++;
  if(a.call_status!=='completed')continue;
  completed++;if(b)b.completed++;
  bump(purpose,a.purpose);bump(service_category,a.service_category);
  if(a.verdict==='spam'){spam++;if(b)b.spam++;}
  const rok=validRespondent(a.respondent_type);const pa=purposeAnalysisAvailable(a.purpose);const pd=rok&&purposeDetermined(a.purpose);const sd=pd&&serviceDetermined(a.service_category);
  if(rok){rOk++;if(b)b.respondent_ok++;}if(pa)pAnalysis++;if(pd)pDetermined++;if(sd)sDetermined++;
}
const steps=[['Chiamate con start_time registrato',rows.length,'A'],['Conversazioni completate',completed,'A'],['Interlocutore determinato',rOk,'B'],['Finalità determinata',pDetermined,'B'],['Categoria/settore determinata',sDetermined,'B']];
const funnel=steps.map((s,i)=>({label:s[0],count:s[1],reliability:s[2],of_total:div(s[1],steps[0][1]),of_previous:i?div(s[1],steps[i-1][1]):1,drop:i?steps[i-1][1]-s[1]:0,drop_rate:i?div(steps[i-1][1]-s[1],steps[i-1][1]):0}));
const dropoff=funnel.slice(1).map((s,i)=>({label:i===0?'Esito tecnico diverso da completed':`${s.label}: non determinato`,drop:s.drop,drop_rate:s.drop_rate,of_total:div(s.drop,steps[0][1])}));
const trend=Object.values(buckets).map(b=>({...b,attempts:b.calls_registered,completed_rate:div(b.completed,b.calls_registered),spam_rate_completed:div(b.spam,b.completed),respondent_coverage:div(b.respondent_ok,b.completed)}));
const warnings=[];if(envUnknown>0)warnings.push(`${envUnknown} record nel periodo hanno ambiente non certificabile e sono esclusi dai KPI produzione.`);
return [{json:{ok:true,generated_at:new Date().toISOString(),range:{from:meta.from_local,to:meta.to_local,days:meta.days,timezone:'Europe/Rome',basis:'mt_call_attempts.start_time'},scope:{production_rule:'test_mode === false',production_rows:rows.length,test_rows_excluded:testCount,environment_unknown_excluded:envUnknown,total_rows_in_range:rowsAll.length},macro:{attempts:rows.length,completed,completed_rate:div(completed,rows.length),spam,spam_rate_completed:div(spam,completed),respondent_coverage:div(rOk,completed),purpose_analysis_available_rate:div(pAnalysis,completed),purpose_determined_rate:div(pDetermined,completed),service_determined_rate:div(sDetermined,completed)},funnel,dropoff,purpose,service_category,trend,data_quality:{respondent_missing:completed-rOk,purpose_analysis_missing:completed-pAnalysis,purpose_not_determined:completed-pDetermined,service_not_determined:completed-sDetermined,test_excluded:testCount,environment_unknown:envUnknown},source_integrity:{rows_expected:expectedN,rows_returned:rowsAll.length,complete:true},warnings}}];

/* ============================================================
   TAG - passo 0: serve rileggere il catalogo?
   Il catalogo tag_id -> nome cambia raramente: viene tenuto nella
   static data del workflow per 6 ore. Se e' fresco questo nodo dice
   "non aggiornare" e la chiamata HTTP non parte affatto.
   Alla prima volta prova piu' path (i 404 sono attesi); appena uno
   risponde il path viene memorizzato e dalle volte successive si
   interroga solo quello.
   NB: la static data si persiste solo nelle esecuzioni di produzione
   (webhook), non nei test manuali dall'editor.
   ============================================================ */
const TTL_MS = 6 * 60 * 60 * 1000;
const BASE = 'https://api.eu.residency.elevenlabs.io';
const CANDIDATI = [
  '/v1/convai/conversations/tags',
  '/v1/convai/tags',
  '/v1/convai/conversation-tags',
  '/v1/convai/workspace/tags'
];

const sd = $getWorkflowStaticData('global');
const cat = sd.tagCatalogo = sd.tagCatalogo || {};

const fresco = cat.mappa
  && cat.aggiornato
  && (Date.now() - cat.aggiornato) < TTL_MS;

if (fresco) return [{ json: { aggiorna: false, da_cache: true } }];

const paths = cat.path ? [cat.path] : CANDIDATI;
return paths.map(p => ({ json: { aggiorna: true, url: BASE + p, path: p } }));

/* ============================================================
   TAG - passo 0b: mappa tag_id -> nome.
   Riceve o le risposte HTTP (ramo "da aggiornare") o niente
   (ramo "cache fresca"). In entrambi i casi emette UN solo item,
   cosi' la lista conversazioni a valle viene chiamata una volta.
   ============================================================ */
const ID_KEYS   = ['tag_id', 'id', 'uuid', 'key'];
const NOME_KEYS = ['name', 'tag_name', 'label', 'title', 'value', 'display_name'];

const sd = $getWorkflowStaticData('global');
const cat = sd.tagCatalogo = sd.tagCatalogo || {};

function risposte(){ try { return $('Tag Catalogo ElevenLabs').all().map(x => x.json); } catch(e){ return []; } }
function candidati(){ try { return $('Tag Catalogo Candidati').all().map(x => x.json); } catch(e){ return []; } }

const mappa = {};
let voci = 0, vincente = null;

function raccogli(obj, prof){
  prof = prof || 0;
  if (!obj || typeof obj !== 'object' || prof > 4) return;
  if (Array.isArray(obj)){ for (const x of obj) raccogli(x, prof + 1); return; }
  const idKey = ID_KEYS.find(k => typeof obj[k] === 'string' && obj[k].trim());
  const nomeKey = NOME_KEYS.find(k => typeof obj[k] === 'string' && obj[k].trim());
  if (idKey && nomeKey){
    const id = String(obj[idKey]).trim();
    if (!mappa[id]){ mappa[id] = String(obj[nomeKey]).trim(); voci++; }
    return;
  }
  for (const k of Object.keys(obj)){
    if (obj[k] && typeof obj[k] === 'object') raccogli(obj[k], prof + 1);
  }
}

const resp = risposte();
const cand = candidati();
resp.forEach((r, i) => {
  if (!r || typeof r !== 'object') return;
  const prima = voci;
  raccogli(r, 0);
  if (voci > prima && !vincente) vincente = cand[i]?.path || null;
});

let fonte;
if (voci > 0){
  cat.mappa = mappa;
  cat.path = vincente || cat.path || null;
  cat.aggiornato = Date.now();
  fonte = 'api';
} else if (cat.mappa){
  fonte = 'cache';
} else {
  fonte = 'nessuna';
}

const finale = voci > 0 ? mappa : (cat.mappa || {});

return [{ json: {
  catalogo: finale,
  diag_catalogo: {
    fonte,
    path: cat.path || null,
    voci: Object.keys(finale).length,
    richieste_fatte: resp.length,
    aggiornato: cat.aggiornato ? new Date(cat.aggiornato).toISOString() : null
  }
} }];

/* ============================================================
   TAG - passo 1: quali giorni vanno letti davvero da ElevenLabs.
   Unico blocco della tab Analisi che NON legge da Directus.
   ============================================================ */
const meta = $('Validate Range').first().json;
const DA = meta.from_local;   // YYYY-MM-DD
const A  = meta.to_local;

const TZ = 'Europe/Rome';
// Un giorno chiuso non cambia piu': i suoi conteggi tag restano in cache.
// Oggi e ieri vengono sempre riletti (conversazioni ancora in corso,
// tag applicati a posteriori). Quindi a regime si scarica ~1 pagina,
// qualunque sia l'ampiezza del range selezionato.
const GIORNI_CACHE_MAX = 120;

const sd = $getWorkflowStaticData('global');
const cache = sd.tagGiorni = sd.tagGiorni || {};

function giornoISO(dt){ return dt.toISODate(); }
function piu(g, n){ return DateTime.fromISO(g, { zone: TZ }).plus({ days: n }).toISODate(); }

const oggi = DateTime.now().setZone(TZ).toISODate();
const ieri = piu(oggi, -1);

// giorni del range richiesto
const giorni = [];
for (let g = DA; g <= A; g = piu(g, 1)) giorni.push(g);

// un giorno e' "fidato" se e' in cache ED e' chiuso (precedente a ieri)
const fidato = g => !!cache[g] && g < ieri;

let daLeggere = giorni.find(g => !fidato(g)) || null;
// range interamente in cache: si legge comunque solo oggi, chiamata corta
if (!daLeggere) daLeggere = oggi;
// non si scende mai sotto ieri: oggi e ieri sono sempre da rileggere
if (daLeggere > ieri) daLeggere = ieri;

// potatura cache
const chiavi = Object.keys(cache).sort();
if (chiavi.length > GIORNI_CACHE_MAX){
  for (const k of chiavi.slice(0, chiavi.length - GIORNI_CACHE_MAX)) delete cache[k];
}

const fromUnix = Math.floor(DateTime.fromISO(daLeggere + 'T00:00:00', { zone: TZ }).toSeconds());

return [{ json: {
  range: { from: DA, to: A },
  leggi_da: daLeggere,
  from_unix: fromUnix,
  giorni_richiesti: giorni.length,
  giorni_da_cache: giorni.filter(fidato).length,
  oggi, ieri
} }];

/* ============================================================
   TAG - passo 2: conteggi, cache giornaliera, nomi dei tag.
   La risposta Directus resta identica: si aggiunge solo "tags".
   ============================================================ */
const base = $('Aggregate Analysis').first().json || {};

const TZ = 'Europe/Rome';

const fin = $('Tag Finestra').first().json || {};
const DA = fin.range?.from, A = fin.range?.to;
const ieri = fin.ieri;

const sd = $getWorkflowStaticData('global');
const cache = sd.tagGiorni = sd.tagGiorni || {};

let catalogo = {}, diagCatalogo = null;
try {
  const c = $('Tag Catalogo Mappa').first().json || {};
  catalogo = c.catalogo || {};
  diagCatalogo = c.diag_catalogo || null;
} catch(e){}

/* ---------- estrazione tag da una conversazione ----------
   Percorso veloce: sulla lista ElevenLabs i tag stanno in "tag_ids"
   al primo livello. La scansione profonda (costosa su migliaia di
   oggetti) parte solo se al primo livello non c'e' nulla. */
const CHIAVI_NOME = ['tags', 'tag', 'labels', 'conversation_tags', 'tag_names'];
const CHIAVI_ID   = ['tag_ids', 'tags_ids', 'tag_id', 'conversation_tag_ids'];
const SALTA = new Set(['transcript', 'messages', 'audio', 'transcript_summary']);

function valori(v, prof){
  prof = prof || 0;
  if (v == null || prof > 3) return [];
  if (typeof v === 'string'){
    const s = v.trim();
    if (!s) return [];
    if (s.startsWith('[') || s.startsWith('{')){
      try { return valori(JSON.parse(s), prof + 1); } catch(e){}
    }
    return s.split(',').map(x => x.trim()).filter(Boolean);
  }
  if (Array.isArray(v)) return v.flatMap(x => valori(x, prof + 1));
  if (typeof v === 'object'){
    const n = v.name ?? v.tag ?? v.label ?? v.value ?? v.tag_name ?? v.tag_id ?? v.id;
    return n == null ? [] : valori(String(n), prof + 1);
  }
  return [];
}

function profondo(obj, prof, out, campi){
  prof = prof || 0;
  if (!obj || typeof obj !== 'object' || prof > 4) return;
  for (const k of Object.keys(obj)){
    if (SALTA.has(k)) continue;
    const v = obj[k];
    if (CHIAVI_NOME.includes(k) || CHIAVI_ID.includes(k)){
      const t = valori(v);
      if (t.length){ out.push(...t); campi.add(k); }
      continue;
    }
    if (v && typeof v === 'object') profondo(v, prof + 1, out, campi);
  }
}

const campiVisti = new Set();
function tokenDi(c){
  const out = [];
  for (const k of CHIAVI_ID.concat(CHIAVI_NOME)){
    if (c[k] != null){
      const t = valori(c[k]);
      if (t.length){ out.push(...t); campiVisti.add(k); }
    }
  }
  if (!out.length) profondo(c, 0, out, campiVisti);
  const visti = new Map();
  for (const t of out){
    const s = String(t).trim(), k = s.toLowerCase();
    if (k && !visti.has(k)) visti.set(k, s);
  }
  return [...visti.values()];
}

/* ---------- pagine lette ---------- */
function pagine(){ try { return $('Tag Lista ElevenLabs').all().map(x => x.json); } catch(e){ return []; } }
const pg = pagine();
const haRisposto = pg.some(p => p && Array.isArray(p.conversations));
const troncato = pg.length ? pg[pg.length - 1]?.has_more === true : false;

const grezze = pg.flatMap(p => (p && Array.isArray(p.conversations)) ? p.conversations : []);
const perId = new Map();
for (const c of grezze){
  const k = c && (c.conversation_id || c.id);
  if (k && !perId.has(k)) perId.set(k, c);
}

function inizio(c){
  let s = Number(c.start_time_unix_secs ?? c.start_time_unix ?? 0);
  if (!isFinite(s) || s <= 0) return 0;
  if (s > 1e12) s = Math.floor(s / 1000);
  return s;
}

/* ---------- bucket per giorno (token grezzi, non risolti) ---------- */
function vuoto(){ return { c: 0, t: 0, m: 0, a: 0, g: {} }; }
const freschi = {};
let senzaData = 0;

for (const [, c] of perId){
  const s = inizio(c);
  if (!s){ senzaData++; continue; }
  const giorno = DateTime.fromSeconds(s, { zone: TZ }).toISODate();
  const b = freschi[giorno] = freschi[giorno] || vuoto();
  b.c++;
  const tk = tokenDi(c);
  if (!tk.length) continue;
  b.t++;
  if (tk.length > 1) b.m++;
  for (const x of tk){ b.g[x] = (b.g[x] || 0) + 1; b.a++; }
}

// I giorni chiusi (precedenti a ieri) entrano in cache: non verranno
// piu' riletti. Oggi e ieri restano fuori, cambiano ancora.
// Se la lettura e' stata troncata i due giorni di bordo possono essere
// parziali (a seconda dell'ordine delle pagine) e non vengono salvati.
const visti = Object.keys(freschi).sort();
const primo = visti[0], ultimo = visti[visti.length - 1];
for (const [giorno, b] of Object.entries(freschi)){
  if (giorno >= ieri) continue;
  if (troncato && (giorno === primo || giorno === ultimo)) continue;
  cache[giorno] = b;
}

/* ---------- somma sul range: cache per i giorni chiusi, fresco per gli altri ---------- */
function piu(g, n){ return DateTime.fromISO(g, { zone: TZ }).plus({ days: n }).toISODate(); }

const lettoDa = fin.leggi_da || DA;
const totale = vuoto();
let daCache = 0, daApi = 0, giorniMancanti = 0;
for (let g = DA; g && A && g <= A; g = piu(g, 1)){
  let b = freschi[g];
  if (b) daApi++;
  else if (cache[g]){ b = cache[g]; daCache++; }
  else if (g >= lettoDa && !troncato){ daApi++; continue; }   // giorno letto, zero chiamate
  else { giorniMancanti++; continue; }                        // giorno mai letto: dato assente
  totale.c += b.c; totale.t += b.t; totale.m += b.m; totale.a += b.a;
  for (const [k, v] of Object.entries(b.g || {})) totale.g[k] = (totale.g[k] || 0) + v;
}

/* ---------- risoluzione token -> nome ---------- */
const nonRisolti = new Set();
const perNome = new Map();
for (const [token, n] of Object.entries(totale.g)){
  let nome = catalogo[token];
  if (!nome){
    // se non e' un id di catalogo puo' essere gia' un nome
    nome = /^[a-z0-9_-]{16,}$/i.test(token) ? ('id:' + token.slice(0, 12)) : token;
    if (nome.startsWith('id:')) nonRisolti.add(token);
  }
  perNome.set(nome, (perNome.get(nome) || 0) + n);
}

const items = [...perNome.entries()]
  .map(([tag, count]) => ({ tag, count, share: totale.a ? count / totale.a : null }))
  .sort((a, b) => (b.count - a.count) || a.tag.localeCompare(b.tag, 'it'));

const diag = {
  giorni_richiesti: fin.giorni_richiesti ?? null,
  giorni_da_cache: daCache,
  giorni_letti_ora: daApi,
  giorni_senza_dato: giorniMancanti,
  letto_da: fin.leggi_da || null,
  pagine_ricevute: pg.length,
  conversazioni_scaricate: perId.size,
  senza_data: senzaData,
  campi_tag: [...campiVisti],
  catalogo: diagCatalogo,
  id_non_risolti: [...nonRisolti].slice(0, 20),
  chiavi_lista: grezze[0] && typeof grezze[0] === 'object' ? Object.keys(grezze[0]).slice(0, 40) : []
};

let tags;
if (!haRisposto){
  tags = { available: false, source: 'elevenlabs', range: { from: DA, to: A },
           error: 'ElevenLabs non ha restituito la lista conversazioni', diag };
} else if (troncato || giorniMancanti > 0){
  tags = { available: false, source: 'elevenlabs', range: { from: DA, to: A },
           error: giorniMancanti > 0 && !troncato
             ? giorniMancanti + ' giorni del periodo non sono ancora stati letti da ElevenLabs'
             : 'periodo troppo ampio per calcolare i tag in una sola lettura: usa un range piu\u0027 corto',
           incomplete: true, days_missing: giorniMancanti, diag };
} else {
  tags = {
    available: true,
    source: 'elevenlabs',
    basis: 'conversazioni ElevenLabs con avvio nel range selezionato',
    range: { from: DA, to: A },
    conversations_total: totale.c,
    conversations_with_tags: totale.t,
    untagged: totale.c - totale.t,
    multi_tag_conversations: totale.m,
    assignments_total: totale.a,
    distinct_tags: items.length,
    items,
    diag
  };
}

return [{ json: Object.assign({}, base, { tags }) }];
